   setInterval(() => {
     fetch('https://api.example.com/data')
       .then(response => response.json())
       .then(data => {
         return data; // 这个 return 值不会传递到外部
       });
   }, 1000);

   console.log(result); // undefined，无法获取到 AJAX 的返回值
   ```

